309	// 矛盾台账上写命令同样失败，且不留下任何业务变化。
310	func TestContradictoryLedgerRejectsWrites(t *testing.T) {
311		dir := t.TempDir()
312		raw := writeLedger(t, dir, func(m map[string]any) { m["next_ticket_seq"] = 1 })
313		for _, args := range [][]string{
314			{"report", "--data-dir", dir, "--asset-id", "EQ-1", "--description", "新故障", "--request-id", "req-9"},
315			{"close", "--data-dir", dir, "--ticket-id", "T0001", "--repair-result", "已修复"},
316			{"register", "--data-dir", dir, "--asset-id", "EQ-2", "--name", "空调", "--location", "二楼"},
317		} {
318			var out, errBuf bytes.Buffer
319			if code := run(args, &out, &errBuf); code != 1 {
320				t.Fatalf("%v 退出码 = %d，应为 1", args[:1], code)
321			}
322			if !strings.Contains(errBuf.String(), "计数器矛盾") {
