332	// 写入失败（目录不可写）不留下部分业务变化，不消耗工单编号与请求绑定；
333	// 恢复写入条件后可重新提交。
334	func TestSaveFailureLeavesNoPartialChange(t *testing.T) {
335		dir := t.TempDir()
336		s, err := openStore(dir)
337		if err != nil {
338			t.Fatal(err)
339		}
340		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
341			t.Fatal(err)
342		}
343		if err := s.save(); err != nil {
344			t.Fatal(err)
345		}
346		before, err := os.ReadFile(filepath.Join(dir, dataFileName))
347		if err != nil {
348			t.Fatal(err)
349		}
350	
351		if _, _, err := s.report("EQ-1", "卡纸", "req-1"); err != nil {
352			t.Fatal(err)
353		}
354		if err := os.Chmod(dir, 0o555); err != nil {
355			t.Fatal(err)
356		}
357		saveErr := s.save()
358		if err := os.Chmod(dir, 0o755); err != nil {
359			t.Fatal(err)
360		}
361		if saveErr == nil {
362			t.Skip("当前环境忽略目录写权限，无法模拟写入失败")
363		}
364		// 原文件字节不变。
365		after, err := os.ReadFile(filepath.Join(dir, dataFileName))
366		if err != nil || !bytes.Equal(after, before) {
367			t.Fatal("写入失败不应改动原文件")
368		}
369		// 重载后看不到部分变化：无工单、无绑定，编号未消耗。
370		s2, err := openStore(dir)
371		if err != nil {
372			t.Fatal(err)
373		}
374		if len(s2.data.Tickets) != 0 || len(s2.data.Requests) != 0 {
375			t.Fatal("写入失败不应留下部分业务变化")
376		}
377		tk, replay, err := s2.report("EQ-1", "卡纸", "req-1")
378		if err != nil || replay || tk.ID != "T0001" {
379			t.Fatalf("恢复写入条件后应能重新提交并得到 T0001: %v replay=%v err=%v", tk, replay, err)
380		}
381		if err := s2.save(); err != nil {
382			t.Fatal(err)
383		}
384		s3, err := openStore(dir)
385		if err != nil {
386			t.Fatal(err)
387		}
388		if got := s3.openTicketOf("EQ-1"); got == nil || got.ID != "T0001" {
389			t.Fatalf("重新提交后应存在未关闭工单 T0001，得到 %v", got)
390		}
391	}
