443	// 编号耗尽时拒绝新报修，但有效台账仍可查询和关闭已有工单。
444	func TestTicketNumberExhaustion(t *testing.T) {
445		dir := t.TempDir()
446		writeLedger(t, dir, func(m map[string]any) {
447			m["next_ticket_seq"] = math.MaxInt
448			appendTo(m, "assets", map[string]any{
