// 派工链相互矛盾的台账：加载即拒绝并保留原文件。
func TestAssignChainContradictions(t *testing.T) {
	// assignedLedger 把 baseLedger 改为合法的已派工台账（一次派工）。
	assignedLedger := func(m map[string]any) {
